Using Morris Traversal - O(n) Time and O(1) SpaceThe idea is to perform an inorder traversal without using recursion or a stack. Morris Traversal temporarily creates links between nodes so that the tree can be traversed using constant extra space. During the traversal, keep track of the previously visited node. If the value of the current node is not greater than the previous node's value, the tree is not a BST. Otherwise, if all the nodes are visited in strictly increasing order, the binary tree is a valid BST. After visiting a node, all the temporary links are removed, restoring the original tree.
            C++

    #include <iostream>
#include <climits>
using namespace std;

// Node structure
class Node {
public:
    int data;
    Node* left;
    Node* right;

    Node(int value) {
        data = value;
        left = right = nullptr;
    }
};

// Function to check if the binary tree 
// is a BST using Morris Traversal
bool isBST(Node* root) {
    Node* curr = root;
    Node* pre = nullptr;
    int prevValue = INT_MIN; 

    while (curr != nullptr) {
        if (curr->left == nullptr) {
            if (curr->data <= prevValue) {

                // Not in ascending order
                return false; 
            }
            prevValue = curr->data;
            curr = curr->right;
        } else {

            // Find the inorder predecessor of curr
            pre = curr->left;
            while (pre->right != nullptr && pre->right != curr) {
                pre = pre->right;
            }

            if (pre->right == nullptr) {

                // Create a temporary 
                // thread to the curr node
                pre->right = curr;
                curr = curr->left;
            } else {

                pre->right = nullptr;

                if (curr->data <= prevValue) {

                    // Not in ascending order
                    return false; 
                }
                prevValue = curr->data;
                curr = curr->right;
            }
        }
    }

    return true; 
}

